import{H as e,ht as t,nt as n,tt as r}from"./chunks/framework.DiAOIirN.js";var i=JSON.parse(`{"title":"FAQ & troubleshooting","description":"","frontmatter":{},"headers":[],"relativePath":"guide/faq.md","filePath":"guide/faq.md","lastUpdated":1787780061000}`),a={name:`guide/faq.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<h1 id="faq-troubleshooting" tabindex="-1">FAQ &amp; troubleshooting <a class="header-anchor" href="#faq-troubleshooting" aria-label="Permalink to “FAQ &amp; troubleshooting”">​</a></h1><h2 id="one-tool-i-expected-is-missing" tabindex="-1">One tool I expected is missing <a class="header-anchor" href="#one-tool-i-expected-is-missing" aria-label="Permalink to “One tool I expected is missing”">​</a></h2><p>Something narrowed the list. In order of likelihood:</p><ul><li><code>IMAP_READ_ONLY</code> is set, and it is a write tool.</li><li><code>IMAP_ALLOW_TOOLS</code> is set and does not name it — it is an allow list, so anything not named is out.</li><li><code>IMAP_DENY_TOOLS</code> names it, possibly through a prefix such as <code>delete_*</code>.</li></ul><p>A filtered tool is not registered at all, so it is missing from <code>tools/list</code> and answers <code>tools/call</code> with &quot;tool not found&quot; — the same as a write tool under read-only. There is no state where it is hidden but still callable.</p><p>What it is <em>not</em> is a typo in one of those variables: an entry that matches no tool stops the server at startup and says which entry it was. See <a href="/guide/configuration#choosing-the-tools-that-load">choosing the tools that load</a>.</p>`,6)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};